## Refactored with Async/Await

Here's the refactored version with several improvements:

```javascript
async function getUser(id) {
  const rows = await db.query('SELECT * FROM users WHERE id = ?', [id]);

  if (!rows.length) {
    throw new Error(`User with id "${id}" not found`);
  }

  return rows[0];
}
```

### Usage Example

```javascript
// Basic usage
try {
  const user = await getUser(1);
  console.log(user);
} catch (err) {
  console.error('Failed to get user:', err.message);
}

// Or with .then()/.catch() if not in an async context
getUser(1)
  .then(user => console.log(user))
  .catch(err => console.error(err.message));
```

---

### What Changed and Why

| Before | After | Reason |
|---|---|---|
| `callback(err)` | `throw new Error(...)` | Errors propagate naturally up the call stack |
| `callback(null, rows[0])` | `return rows[0]` | Return values are cleaner and composable |
| Nested callbacks | Linear `await` | Easier to read and maintain |
| Generic error message | Includes the `id` | More useful for debugging |

---

### Important Caveat

This assumes `db.query` **already returns a Promise**. If it's still callback-based (e.g., older `mysql` package), you'll need to promisify it first:

```javascript
// Option 1 — Node's built-in util.promisify
const { promisify } = require('util');
const dbQuery = promisify(db.query.bind(db));

async function getUser(id) {
  const rows = await dbQuery('SELECT * FROM users WHERE id = ?', [id]);
  if (!rows.length) throw new Error(`User with id "${id}" not found`);
  return rows[0];
}

// Option 2 — Manual Promise wrapper (if promisify doesn't work well)
function dbQuery(sql, params) {
  return new Promise((resolve, reject) => {
    db.query(sql, params, (err, rows) => {
      if (err) reject(err);
      else resolve(rows);
    });
  });
}
```

> **Tip:** Modern database libraries like `mysql2`, `pg`, and `better-sqlite3` support Promises natively, so you can skip the promisify step entirely.
